#!/usr/bin/env bash
# SPDX-License-Identifier: LGPL-3.0-only
# SPDX-FileCopyrightText: Copyright (C) 2026 mplx <mplx@jennifer-lang.dev>
#
# Stamp a version into src/topics/version.j, the VERSION constant a deck may
# export.
#
# Opt-in. A deck that wants `<slug>.VERSION` to say which build it is creates
# src/topics/version.j once, carrying the line
#
#   # <slug> - generated by tools/inject-version.sh. Do not edit.
#
# and from then on CI regenerates it on every run. A deck without that file -
# or with a hand-kept one - is left alone, so the workflows call this
# unconditionally. Only a topics deck can opt in: the file is `include`d into
# the entry module, and has no overlay of its own.
#
# This does NOT touch the manifest. package.version is authored and committed,
# because jvc resolves against the manifest on the default branch: it reads
# package.urls.deck, which points at the raw manifest on main. A version that
# only ever existed inside a CI workspace would leave jvc resolving whatever was
# last committed. Bump the manifest, then tag to match; release.yml refuses a
# tag that disagrees.
#
# The stamp is the tag on a release, <tag>-dev+<commits>.<sha> on a branch -
# see tools/version.sh.
#
# Usage: tools/inject-version.sh [version]   (default: tools/version.sh)
set -euo pipefail
cd "$(dirname "$0")/.."
# shellcheck source=tools/deck-lib.sh
source tools/deck-lib.sh
deck_load

target=src/topics/version.j
marker="generated by tools/inject-version.sh"

if [[ ! -f "$target" ]] || ! grep -qF -- "$marker" "$target"; then
    echo "no generated ${target} in this deck - nothing to inject"
    exit 0
fi

version="${1:-$(tools/version.sh)}"

# Semver, optionally with a -dev prerelease and +build metadata.
if [[ ! "$version" =~ ^[0-9]+\.[0-9]+\.[0-9]+(-[0-9A-Za-z.-]+)?(\+[0-9A-Za-z.-]+)?$ ]]; then
    deck_die "\"${version}\" is not a semver version"
fi

# The copyright line is the deck's own, so keep whatever the file carries.
copyright="$(grep -m1 '^# SPDX-FileCopyrightText: ' "$target" || true)"
[[ -n "$copyright" ]] || deck_die "${target} has no SPDX-FileCopyrightText line to keep"

cat > "$target" <<EOF
# SPDX-License-Identifier: ${DECK_LICENSE}
${copyright}
# pragma-jennifer-version: ${DECK_FLOOR}
# ci-no-overlay

# ${DECK_SLUG} - ${marker}. Do not edit.
# Spliced into ${DECK_SLUG}.j via include - not a standalone module.

/**
 * The version of this deck.
 *
 * Injected from the git tag the build came from: \`0.2.0\` on a release,
 * \`0.2.0-dev+14.9ebf3dd\` anywhere else. See tools/version.sh.
 */
export def const VERSION as string init "${version}";
EOF

echo "injected ${version} into ${target}"
